package ktanesolver.module.modded.regular.oddoneout;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;class OddOneOutSolverTest{@Test void findsUniquelyFrequentFinalPosition(){OddOneOutSolver s=new OddOneOutSolver();ModuleEntity m=new ModuleEntity();for(int p:new int[]{1,2,1,2})s.solve(new RoundEntity(),new BombEntity(),m,new OddOneOutInput(p));@SuppressWarnings("unchecked")OddOneOutOutput o=((SolveSuccess<OddOneOutOutput>)s.solve(new RoundEntity(),new BombEntity(),m,new OddOneOutInput(3))).output();assertThat(o.finalPosition()).isEqualTo(3);assertThat(o.command()).isEqualTo("press 3");}}
